# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: emit
def emit(xs, limit=12):
    return [v if v <= limit else limit for v in xs[1:]]

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: gather
def gather(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return gather(intake(emit(render(raw))))

